<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { router } from '@inertiajs/vue3'
import { route } from 'ziggy-js'
import type { CargoOption, CargoPreview } from '../../types'

const props = defineProps<{ filters: { edificio_id?: string | null, periodo?: string | null, concepto_cobro_id?: string | null }, preview: CargoPreview | null, edificios: Array<{ id: string, nombre: string }>, conceptos: CargoOption[] }>()
const currentPeriod = (() => { const now = new Date(); return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}` })()
const form = reactive({ edificio_id: props.filters.edificio_id ?? '', periodo: props.filters.periodo ?? currentPeriod, concepto_cobro_id: props.filters.concepto_cobro_id ?? '' })
const loading = ref(false)
const concepts = computed(() => props.conceptos.filter(item => item.edificioId === form.edificio_id && item.estado === 'activo').map(item => ({ label: `${item.codigo} · ${item.nombre}`, value: item.id })))
const loadPreview = () => router.get(route('cargos.generate'), { ...form, concepto_cobro_id: form.concepto_cobro_id || undefined }, { preserveState: true, replace: true, onStart: () => { loading.value = true }, onFinish: () => { loading.value = false } })
const generate = () => { if (!form.edificio_id) return; router.post(route('cargos.generate.store', form.edificio_id), { periodo: form.periodo, concepto_cobro_id: form.concepto_cobro_id || null }, { onStart: () => { loading.value = true }, onFinish: () => { loading.value = false } }) }
</script>

<template>
  <UDashboardPanel id="cargos-generate"><template #header><UDashboardNavbar title="Generación de cargos"><template #leading><UDashboardSidebarCollapse /></template></UDashboardNavbar></template><template #body><div class="mx-auto flex w-full max-w-6xl flex-col gap-6 p-4 sm:p-6"><UCard><div class="grid gap-4 md:grid-cols-3"><UFormField label="Edificio" required><USelect v-model="form.edificio_id" :items="edificios.map(item => ({ label: item.nombre, value: item.id }))" placeholder="Seleccione edificio" required size="xl" @update:model-value="form.concepto_cobro_id = ''" /></UFormField><UFormField label="Período" required><UInput v-model="form.periodo" type="month" required size="xl" /></UFormField><UFormField label="Concepto" hint="Todos los activos si se omite"><USelect v-model="form.concepto_cobro_id" :items="[{ label: 'Todos los conceptos activos', value: '' }, ...concepts]" size="xl" /></UFormField></div><div class="mt-5 flex justify-end"><UButton icon="i-lucide-search" label="Previsualizar" :disabled="!form.edificio_id || !form.periodo" :loading="loading" @click="loadPreview" /></div></UCard><UCard v-if="preview"><template #header><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="font-semibold text-highlighted">Previsualización · {{ preview.periodo }}</p><p class="mt-1 text-sm text-muted">No se ha persistido ningún cargo.</p></div><div class="text-right"><p class="font-mono text-lg font-semibold text-highlighted">${{ preview.totalValor }}</p><p class="text-xs text-muted">{{ preview.cantidadCargos }} cargo(s) calculado(s)</p></div></div></template><div class="overflow-x-auto"><table class="w-full min-w-4xl text-left text-sm"><thead class="border-b border-default text-xs uppercase text-muted"><tr><th class="px-3 py-3">Departamento</th><th class="px-3 py-3">Concepto</th><th class="px-3 py-3">Cálculo</th><th class="px-3 py-3">Tarifa</th><th class="px-3 py-3">Base</th><th class="px-3 py-3">Valor</th></tr></thead><tbody class="divide-y divide-default"><tr v-for="item in preview.cargos" :key="`${item.departamentoId}-${item.conceptoId}`"><td class="px-3 py-3 font-medium">{{ item.departamento }}</td><td class="px-3 py-3">{{ item.concepto }}</td><td class="px-3 py-3 text-muted">{{ item.formaCalculo }}</td><td class="px-3 py-3 font-mono">{{ item.tarifa ?? '—' }}</td><td class="px-3 py-3 font-mono">{{ item.base ?? '—' }}</td><td class="px-3 py-3 font-mono font-semibold">${{ item.valor }}</td></tr></tbody></table></div><UAlert v-if="preview.advertencias.length" class="mt-5" color="warning" :description="`${preview.advertencias.length} advertencia(s), incluidos ${preview.cantidadOmitidos} cargo(s) omitido(s).`" icon="i-lucide-triangle-alert" variant="subtle" /><ul v-if="preview.advertencias.length" class="mt-3 space-y-1 text-sm text-muted"><li v-for="(warning, index) in preview.advertencias" :key="index">{{ warning.codigo }}: {{ warning.departamento || warning.concepto || 'Edificio' }} · {{ warning.mensaje }}</li></ul><template #footer><div class="flex justify-end"><UButton icon="i-lucide-wand-sparkles" label="Generar cargos" :disabled="!preview.cantidadCargos" :loading="loading" @click="generate" /></div></template></UCard></div></template></UDashboardPanel>
</template>
